import os
import re
import pytesseract
from PIL import Image, ImageOps

# Reuse functions from process_receipts.py
KEYWORDS_PRIORITY = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL']
]

EXCLUSION_KEYWORDS = [
    'SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED'
]

def preprocess_image(image_path):
    try:
        img = Image.open(image_path)
        img = ImageOps.grayscale(img)
        img = ImageOps.autocontrast(img)
        return img
    except Exception as e:
        return Image.open(image_path)

def parse_amount_from_line(line):
    matches = re.findall(r'\b\d{1,3}(?:,\d{3})*\.\d{2}\b', line)
    if matches:
        return matches[-1]
    matches_simple = re.findall(r'\b\d+\.\d{2}\b', line)
    if matches_simple:
        return matches_simple[-1]
    return None

def extract_total(text):
    lines = [line.strip() for line in text.split('\n') if line.strip()]
    for keyword_group in KEYWORDS_PRIORITY:
        for i, line in enumerate(lines):
            line_upper = line.upper()
            if any(excl in line_upper for excl in EXCLUSION_KEYWORDS):
                continue
            if any(kw in line_upper for kw in keyword_group):
                print(f"  Matched keyword in line: {line}")
                amount = parse_amount_from_line(line)
                if amount:
                    return amount.replace(',', '')
                if i + 1 < len(lines):
                    next_line = lines[i+1]
                    print(f"  Checking next line: {next_line}")
                    amount = parse_amount_from_line(next_line)
                    if amount:
                        return amount.replace(',', '')
    return None

def main():
    files = ['052.jpg', '069.jpg', '071.jpg']
    for filename in files:
        filepath = os.path.join('/app/workspace/dataset/img', filename)
        if not os.path.exists(filepath):
            continue

        print(f"--- Processing {filename} ---")
        img = preprocess_image(filepath)
        text = pytesseract.image_to_string(img, config='--psm 6')
        print("Raw Text:")
        print(text)
        print("-" * 20)

        total = extract_total(text)
        print(f"Extracted Total: {total}")
        print("=" * 30)

if __name__ == "__main__":
    main()

