import os
import re
import pytesseract
from PIL import Image, ImageOps
from openpyxl import Workbook
from datetime import datetime
import warnings

# Suppress warnings
warnings.filterwarnings("ignore")

# Set up paths
IMG_DIR = '/app/workspace/dataset/img'
OUTPUT_FILE = '/app/workspace/stat_ocr.xlsx'

# Keywords config
KEYWORDS_PRIORITY = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL']
]

EXCLUSION_KEYWORDS = [
    'SUBTOTAL', 'SUB TOTAL', 'DISCOUNT', 'CHANGE', 'CASH TENDERED'
]

CONDITIONAL_EXCLUSION_KEYWORDS = [
    'TAX', 'GST', 'SST'
]

def preprocess_image(image_path, upscale=False):
    """
    Preprocessing to improve OCR accuracy.
    Converts to grayscale, applies auto-contrast.
    Optionally upscales.
    """
    try:
        img = Image.open(image_path)
        img = ImageOps.grayscale(img)
        img = ImageOps.autocontrast(img)

        if upscale:
            width, height = img.size
            new_size = (width * 2, height * 2)
            img = img.resize(new_size, Image.Resampling.LANCZOS)

        return img
    except Exception as e:
        print(f"Warning: preprocessing failed for {image_path}, using original. Error: {e}")
        return Image.open(image_path)

def parse_date_string(date_str):
    date_str = date_str.strip()
    formats = [
        '%d/%m/%Y', '%d-%m-%Y', '%d.%m.%Y',
        '%Y-%m-%d', '%Y/%m/%d', '%Y.%m.%d',
        '%d/%m/%y', '%d-%m-%y', '%d.%m.%y',
        '%d %b %Y', '%d %b %y', 
        '%b %d %Y', '%b %d, %Y', 
        '%d %B %Y',
    ]
    for fmt in formats:
        try:
            dt = datetime.strptime(date_str, fmt)
            if 2010 <= dt.year <= 2030:
                return dt.strftime('%Y-%m-%d')
        except ValueError:
            continue
    return None

def extract_date(text):
    date_patterns = [
        r'\b\d{1,2}[-/.]\d{1,2}[-/.]\d{2,4}\b', 
        r'\b\d{2,4}[-/.]\d{1,2}[-/.]\d{1,2}\b',  
        r'\b\d{1,2}\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+\d{2,4}\b', 
        r'\b(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+\d{1,2},?\s+\d{2,4}\b'
    ]
    lines = text.split('\n')
    for line in lines:
        for pattern in date_patterns:
            matches = re.findall(pattern, line, re.IGNORECASE)
            for match in matches:
                parsed = parse_date_string(match)
                if parsed:
                    return parsed
    return None

def parse_amount_from_line(line):
    matches = re.findall(r'\b\d{1,3}(?:,\d{3})*\.\d{2}\b', line)
    if matches:
        return matches[-1]
    matches_simple = re.findall(r'\b\d+\.\d{2}\b', line)
    if matches_simple:
        return matches_simple[-1]
    return None

def extract_total(text):
    lines = [line.strip() for line in text.split('\n') if line.strip()]
    for keyword_group in KEYWORDS_PRIORITY:
        for i, line in enumerate(lines):
            line_upper = line.upper()
            skip_line = False

            if any(excl in line_upper for excl in EXCLUSION_KEYWORDS):
                skip_line = True

            if not skip_line:
                for excl in CONDITIONAL_EXCLUSION_KEYWORDS:
                    if excl in line_upper:
                        idx_total = line_upper.find('TOTAL')
                        idx_excl = line_upper.find(excl)
                        if idx_total != -1 and idx_total < idx_excl:
                            pass
                        else:
                            skip_line = True
                            break

            if skip_line:
                continue

            if any(kw in line_upper for kw in keyword_group):
                amount = parse_amount_from_line(line)
                if amount:
                    return amount.replace(',', '')
                if i + 1 < len(lines):
                    next_line = lines[i+1]
                    amount = parse_amount_from_line(next_line)
                    if amount:
                        return amount.replace(',', '')
    return None

def process_file(filepath, upscale=False):
    try:
        img = preprocess_image(filepath, upscale=upscale)
        text = pytesseract.image_to_string(img, config='--psm 6')
        extracted_date = extract_date(text)
        extracted_total = extract_total(text)

        final_amount = None
        if extracted_total:
            try:
                val = float(extracted_total)
                final_amount = "{:.2f}".format(val)
            except:
                final_amount = None

        return extracted_date, final_amount
    except Exception as e:
        print(f"Error processing {filepath} (upscale={upscale}): {e}")
        return None, None

def main():
    if not os.path.exists(IMG_DIR):
        print(f"Error: Directory {IMG_DIR} not found.")
        return

    files = sorted([f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png'))])

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(['filename', 'date', 'total_amount'])

    print(f"Processing {len(files)} images...")

    for filename in files:
        filepath = os.path.join(IMG_DIR, filename)

        # Pass 1: Normal
        date, total = process_file(filepath, upscale=False)

        # Pass 2: Upscale if missing data
        if date is None or total is None:
            date_up, total_up = process_file(filepath, upscale=True)
            if date is None and date_up is not None:
                date = date_up
            if total is None and total_up is not None:
                total = total_up

        ws.append([filename, date, total])

    try:
        wb.save(OUTPUT_FILE)
        print(f"Successfully wrote results to {OUTPUT_FILE}")
    except Exception as e:
        print(f"Error writing Excel file: {e}")

if __name__ == "__main__":
    main()

